    51	/* When moving a client from IO thread to main thread we may need to update
    52	 * some of its variables as they are duplicated to avoid contention with main
    53	 * thread.
    54	 * For now this is valid only for master or slave clients. */
    55	void updateClientDataFromIOThread(client *c) {
    56	    if (!(c->flags & CLIENT_MASTER) && !(c->flags & CLIENT_SLAVE)) return;
    57	
    58	    serverAssert(c->tid != IOTHREAD_MAIN_THREAD_ID &&
    59	                 c->running_tid == IOTHREAD_MAIN_THREAD_ID);
    60	
    61	    if (c->io_repl_ack_time > c->repl_ack_time) {
    62	        serverAssert(c->flags & CLIENT_SLAVE);
    63	        c->repl_ack_time = c->io_repl_ack_time;
    64	    }
    65	    if (c->io_lastinteraction > c->lastinteraction) {
    66	        serverAssert(c->flags & CLIENT_MASTER);
    67	        c->lastinteraction = c->io_lastinteraction;
    68	    }
    69	    if (c->io_read_reploff > c->read_reploff) {
    70	        serverAssert(c->flags & CLIENT_MASTER);
    71	        c->read_reploff = c->io_read_reploff;
    72	    }
    73	
    74	    /* Update replication buffer referenced node if IO thread has sent some data. */
    75	    if (c->flags & CLIENT_SLAVE && c->ref_repl_buf_node != NULL &&
    76	        (c->io_curr_repl_node != c->ref_repl_buf_node ||
    77	         c->io_curr_block_pos != c->ref_block_pos))
    78	    {
    79	        ((replBufBlock*)listNodeValue(c->ref_repl_buf_node))->refcount--;
    80	        ((replBufBlock*)listNodeValue(c->io_curr_repl_node))->refcount++;
