   112	/* When IO threads read a complete query of clients or want to free clients, it
   113	 * should remove it from its clients list and put the client in the list to main
   114	 * thread, we will send these clients to main thread in IOThreadBeforeSleep. */
   115	void enqueuePendingClientsToMainThread(client *c, int unbind) {
   116	    /* If the IO thread may no longer manage it, such as closing client, we should
   117	     * unbind client from event loop, so main thread doesn't need to do it costly. */
   118	    if (unbind) {
   119	        /* Drop it from the event loop's pending decompression list first, while
   120	         * c->conn->el is still valid. */
   121	        clientCompressionPendingRemove(c);
   122	        connUnbindEventLoop(c->conn);
   123	    }
   124	    /* Just skip if it already is transferred. */
   125	    if (c->io_thread_client_list_node) {
   126	        IOThread *t = &IOThreads[c->tid];
   127	        /* If there are several clients to process, let the main thread handle them ASAP.
   128	         * Since the client being added to the queue may still need to be processed by
   129	         * the IO thread, we must call this before adding it to the queue to avoid
   130	         * races with the main thread. */
   131	        sendPendingClientsToMainThreadIfNeeded(t, 1);
   132	        /* Disable read and write to avoid race when main thread processes. */
   133	        c->io_flags &= ~(CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED);
   134	        /* Remove the client from IO thread, add it to main thread's pending list. */
   135	        listUnlinkNode(t->clients, c->io_thread_client_list_node);
   136	        listLinkNodeTail(t->pending_clients_to_main_thread, c->io_thread_client_list_node);
   137	        c->io_thread_client_list_node = NULL;
   138	
   139	        if (c->io_thread_compression_clients_node) {
   140	            listDelNode(t->compression_clients, c->io_thread_compression_clients_node);
   141	            c->io_thread_compression_clients_node = NULL;
   142	        }
   143	    }
   144	}
