   332	/* When the main thread accepts a new client or transfers clients to IO threads,
   333	 * it assigns the client to the IO thread with the fewest clients. */
   334	void assignClientToIOThread(client *c) {
   335	    serverAssert(c->tid == IOTHREAD_MAIN_THREAD_ID);
   336	    /* Find the IO thread with the fewest clients. */
   337	    int min_id = 0;
   338	    int min = INT_MAX;
   339	    for (int i = 1; i < server.io_threads_num; i++) {
   340	        if (server.io_threads_clients_num[i] < min) {
   341	            min = server.io_threads_clients_num[i];
   342	            min_id = i;
   343	        }
   344	    }
   345	
   346	    /* Assign the client to the IO thread. */
   347	    server.io_threads_clients_num[c->tid]--;
   348	    c->tid = min_id;
   349	    server.io_threads_clients_num[min_id]++;
   350	
   351	    /* The client running in IO thread needs to have deferred objects array. */
   352	    c->deferred_objects = zmalloc(sizeof(deferredObject) * CLIENT_MAX_DEFERRED_OBJECTS);
   353	
   354	    /* Unbind connection of client from main thread event loop, disable read and
   355	     * write, and then put it in the list, main thread will send these clients
   356	     * to IO thread in beforeSleep. */
   357	    connUnbindEventLoop(c->conn);
   358	    c->io_flags &= ~(CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED | CLIENT_IO_COMPRESSION_ENABLED);
   359	
   360	    enqueuePendingClienstToIOThreads(c);
   361	}
