   990	/* Initialize the data structures needed for threaded I/O. */
   991	void initThreadedIO(void) {
   992	    if (server.io_threads_num <= 1) return;
   993	
   994	    server.io_threads_active = 1;
   995	
   996	    if (server.io_threads_num > IO_THREADS_MAX_NUM) {
   997	        serverLog(LL_WARNING,"Fatal: too many I/O threads configured. "
   998	                             "The maximum number is %d.", IO_THREADS_MAX_NUM);
   999	        exit(1);
  1000	    }
  1001	
  1002	    /* Spawn and initialize the I/O threads. */
  1003	    for (int i = 1; i < server.io_threads_num; i++) {
  1004	        IOThread *t = &IOThreads[i];
  1005	        t->id = i;
  1006	        t->el = aeCreateEventLoop(server.maxclients+CONFIG_FDSET_INCR);
  1007	        t->el->privdata[0] = t;
  1008	        t->pending_clients = listCreate();
  1009	        t->processing_clients = listCreate();
  1010	        t->pending_clients_to_main_thread = listCreate();
  1011	        t->clients = listCreate();
  1012	        t->compression_clients = listCreate();
  1013	        t->cronloops = 0;
  1014	        atomicSetWithSync(t->paused, IO_THREAD_UNPAUSED);
  1015	        atomicSetWithSync(t->running, 0);
  1016	
  1017	        pthread_mutexattr_t *attr = NULL;
  1018	        #if defined(__linux__) && defined(__GLIBC__)
  1019	        attr = zmalloc(sizeof(pthread_mutexattr_t));
  1020	        pthread_mutexattr_init(attr);
  1021	        pthread_mutexattr_settype(attr, PTHREAD_MUTEX_ADAPTIVE_NP);
  1022	        #endif
  1023	        pthread_mutex_init(&t->pending_clients_mutex, attr);
  1024	
  1025	        t->pending_clients_notifier = createEventNotifier();
  1026	        if (aeCreateFileEvent(t->el, getReadEventFd(t->pending_clients_notifier),
  1027	                              AE_READABLE, handleClientsFromMainThread, t) != AE_OK)
  1028	        {
  1029	            serverLog(LL_WARNING, "Fatal: Can't register file event for IO thread notifications.");
  1030	            exit(1);
  1031	        }
  1032	
  1033	        /* This is the timer callback of the IO thread, used to gradually handle 
  1034	         * some background operations, such as clients cron. */
  1035	        if (aeCreateTimeEvent(t->el, 1, IOThreadCron, t, NULL) == AE_ERR) {
  1036	            serverLog(LL_WARNING, "Fatal: Can't create event loop timers in IO thread.");
  1037	            exit(1);
  1038	        }
  1039	
  1040	        /* Create IO thread */
  1041	        if (pthread_create(&t->tid, NULL, IOThreadMain, (void*)t) != 0) {
  1042	            serverLog(LL_WARNING, "Fatal: Can't initialize IO thread.");
  1043	            exit(1);
  1044	        }
  1045	
  1046	        /* For main thread */
  1047	        mainThreadPendingClientsToIOThreads[i] = listCreate();
  1048	        mainThreadPendingClients[i] = listCreate();
  1049	        mainThreadProcessingClients[i] = listCreate();
  1050	        pthread_mutex_init(&mainThreadPendingClientsMutexes[i], attr);
  1051	        mainThreadPendingClientsNotifiers[i] = createEventNotifier();
  1052	        if (aeCreateFileEvent(server.el, getReadEventFd(mainThreadPendingClientsNotifiers[i]),
  1053	                              AE_READABLE, handleClientsFromIOThread, t) != AE_OK)
  1054	        {
  1055	            serverLog(LL_WARNING, "Fatal: Can't register file event for main thread notifications.");
  1056	            exit(1);
  1057	        }
  1058	        if (attr) zfree(attr);
  1059	    }
  1060	}
