  1062	/* Kill the IO threads, TODO: release the applied resources. */
  1063	void killIOThreads(void) {
  1064	    if (server.io_threads_num <= 1) return;
  1065	
  1066	    int err, j;
  1067	    for (j = 1; j < server.io_threads_num; j++) {
  1068	        if (IOThreads[j].tid == pthread_self()) continue;
  1069	        if (IOThreads[j].tid && pthread_cancel(IOThreads[j].tid) == 0) {
  1070	            if ((err = pthread_join(IOThreads[j].tid,NULL)) != 0) {
  1071	                serverLog(LL_WARNING,
  1072	                    "IO thread(tid:%lu) can not be joined: %s",
  1073	                        (unsigned long)IOThreads[j].tid, strerror(err));
  1074	            } else {
  1075	                serverLog(LL_WARNING,
  1076	                    "IO thread(tid:%lu) terminated",(unsigned long)IOThreads[j].tid);
  1077	            }
  1078	        }
  1079	    }
  1080	}
  1935	 * for ready file descriptors.
  1936	 *
  1937	 * Note: This function is (currently) called from two functions:
  1938	 * 1. aeMain - The main server loop
  1939	 * 2. processEventsWhileBlocked - Process clients during RDB/AOF load
  1940	 *
  1941	 * If it was called from processEventsWhileBlocked we don't want
  1942	 * to perform all actions (For example, we don't want to expire
  1943	 * keys), but we do need to perform some actions.
  1944	 *
  1945	 * The most important is freeClientsInAsyncFreeQueue but we also
  1946	 * call some other low-risk functions. */
  1947	void beforeSleep(struct aeEventLoop *eventLoop) {
  1948	    UNUSED(eventLoop);
  1949	
  1950	    updatePeakMemory();
  1951	
  1952	    /* Just call a subset of vital functions in case we are re-entering
  1953	     * the event loop from processEventsWhileBlocked(). Note that in this
  1954	     * case we keep track of the number of events we are processing, since
  1955	     * processEventsWhileBlocked() wants to stop ASAP if there are no longer
  1956	     * events to handle. */
  1957	    if (ProcessingEventsWhileBlocked) {
  1958	        uint64_t processed = 0;
  1959	        processed += connTypeProcessPendingData(server.el);
  1960	        processed += clientCompressionProcessPendingData(server.el);
  1961	        if (server.aof_state == AOF_ON || server.aof_state == AOF_WAIT_REWRITE)
  1962	            flushAppendOnlyFile(0);
  1963	        processed += handleClientsWithPendingWrites();
  1964	        processed += freeClientsInAsyncFreeQueue();
  1965	
  1966	        /* Let the clients after the blocking call be processed. */
  1967	        processClientsOfAllIOThreads();
  1968	        /* New connections may have been established while blocked, clients from
  1969	         * IO thread may have replies to write, ensure they are promptly sent to
  1970	         * IO threads. */
  1971	        processed += sendPendingClientsToIOThreads();
  1972	
  1973	        server.events_processed_while_blocked += processed;
  1974	        return;
  1975	    }
  1976	
  1977	    /* Handle pending data(typical TLS). (must be done before flushAppendOnlyFile) */
  1978	    connTypeProcessPendingData(server.el);
  1979	    /* Drain any buffered decompressed replication data (see client_comp.c). */
  1980	    clientCompressionProcessPendingData(server.el);
  1981	
  1982	    /* If any connection type(typical TLS) or compression still has
  1983	     * pending unread data don't sleep at all. */
  1984	    int dont_sleep = connTypeHasPendingData(server.el) ||
  1985	                     clientCompressionHasPendingData(server.el);
  1986	
  1987	    /* Call the Redis Cluster before sleep function. Note that this function
  1988	     * may change the state of Redis Cluster (from ok to fail or vice versa),
  1989	     * so it's a good idea to call it before serving the unblocked clients
  1990	     * later in this function, must be done before blockedBeforeSleep. */
  1991	    if (server.cluster_enabled) {
  1992	        clusterBeforeSleep();
  1993	        asmBeforeSleep();
  1994	    }
  1995	
  1996	    /* Handle blocked clients.
  1997	     * must be done before flushAppendOnlyFile, in case of appendfsync=always,
  1998	     * since the unblocked clients may write data. */
  1999	    blockedBeforeSleep();
  2000	
  2001	    /* Record cron time in beforeSleep, which is the sum of active-expire, active-defrag and all other
  2002	     * tasks done by cron and beforeSleep, but excluding read, write and AOF, that are counted by other
  2003	     * sets of metrics. */
  2004	    monotime cron_start_time_before_aof = getMonotonicUs();
  2005	
  2006	    /* Run a fast expire cycle (the called function will return
  2007	     * ASAP if a fast cycle is not needed). */
  2008	    if (server.active_expire_enabled && iAmMaster())
  2009	        activeExpireCycle(ACTIVE_EXPIRE_CYCLE_FAST);
  2010	
  2011	    if (moduleCount()) {
  2012	        moduleFireServerEvent(REDISMODULE_EVENT_EVENTLOOP,
  2013	                              REDISMODULE_SUBEVENT_EVENTLOOP_BEFORE_SLEEP,
  2014	                              NULL);
  2015	    }
  2016	
  2017	    /* Send all the slaves an ACK request if at least one client blocked
  2018	     * during the previous event loop iteration. Note that we do this after
  2019	     * processUnblockedClients(), so if there are multiple pipelined WAITs
  2020	     * and the just unblocked WAIT gets blocked again, we don't have to wait
  2021	     * a server cron cycle in absence of other event loop events. See #6623.
  2022	     * 
  2023	     * We also don't send the ACKs while clients are paused, since it can
  2024	     * increment the replication backlog, they'll be sent after the pause
  2025	     * if we are still the master. */
  2026	    if (server.get_ack_from_slaves && !isPausedActionsWithUpdate(PAUSE_ACTION_REPLICA)) {
  2027	        sendGetackToReplicas();
  2028	        server.get_ack_from_slaves = 0;
  2029	    }
  2030	
  2031	    /* We may have received updates from clients about their current offset. NOTE:
  2032	     * this can't be done where the ACK is received since failover will disconnect 
  2033	     * our clients. */
  2034	    updateFailoverStatus();
  2035	
  2036	    /* Since we rely on current_client to send scheduled invalidation messages
  2037	     * we have to flush them after each command, so when we get here, the list
  2038	     * must be empty. */
  2039	    serverAssert(listLength(server.tracking_pending_keys) == 0);
  2040	    serverAssert(listLength(server.pending_push_messages) == 0);
  2041	
  2042	    /* Send the invalidation messages to clients participating to the
  2043	     * client side caching protocol in broadcasting (BCAST) mode. */
  2044	    trackingBroadcastInvalidationMessages(NULL);
  2045	
  2046	    /* Record time consumption of AOF writing. */
  2047	    monotime aof_start_time = getMonotonicUs();
  2048	    /* Record cron time in beforeSleep. This does not include the time consumed by AOF writing and IO writing below. */
  2049	    monotime duration_before_aof = aof_start_time - cron_start_time_before_aof;
  2050	    /* Record the fsync'd offset before flushAppendOnly */
  2051	    long long prev_fsynced_reploff = server.fsynced_reploff;
  2052	
  2053	    /* Write the AOF buffer on disk,
  2054	     * must be done before handleClientsWithPendingWrites and
  2055	     * sendPendingClientsToIOThreads, in case of appendfsync=always. */
  2056	    if (server.aof_state == AOF_ON || server.aof_state == AOF_WAIT_REWRITE)
  2057	        flushAppendOnlyFile(0);
  2058	
  2059	    /* Record time consumption of AOF writing. */
  2060	    durationAddSample(EL_DURATION_TYPE_AOF, getMonotonicUs() - aof_start_time);
  2061	
  2062	    /* Update the fsynced replica offset.
  2063	     * If an initial rewrite is in progress then not all data is guaranteed to have actually been
  2064	     * persisted to disk yet, so we cannot update the field. We will wait for the rewrite to complete. */
  2065	    if (server.aof_state == AOF_ON && server.fsynced_reploff != -1) {
  2066	        long long fsynced_reploff_pending;
  2067	        atomicGet(server.fsynced_reploff_pending, fsynced_reploff_pending);
  2068	        server.fsynced_reploff = fsynced_reploff_pending;
  2069	
  2070	        /* If we have blocked [WAIT]AOF clients, and fsynced_reploff changed, we want to try to
  2071	         * wake them up ASAP. */
  2072	        if (listLength(server.clients_waiting_acks) && prev_fsynced_reploff != server.fsynced_reploff)
  2073	            dont_sleep = 1;
  2074	    }
  2075	
  2076	    if (server.io_threads_num > 1) {
  2077	        /* Corresponding to IOThreadBeforeSleep, process the clients from IO threads
