   522	/* Prefetch the commands from the IO thread. The return value is the number
   523	 * of clients that have been prefetched. */
   524	int prefetchIOThreadCommands(IOThread *t) {
   525	    int len = listLength(mainThreadProcessingClients[t->id]);
   526	    int to_prefetch = determinePrefetchCount(len);
   527	    if (to_prefetch == 0) return 0;
   528	
   529	    /* Two-phase approach to optimize cache utilization:
   530	     * Phase 1: Issue prefetch hints for client structures
   531	     * Phase 2: Access the now-cached client data and add commands to batch */
   532	    /* Since we double the configured size for better performance,
   533	     * see also `determinePrefetchCount` */
   534	    static client *c[PREFETCH_BATCH_MAX_SIZE*2];
   535	    serverAssert(PREFETCH_BATCH_MAX_SIZE*2 >= to_prefetch );
   536	    int clients = 0;
   537	    listIter li;
   538	    listNode *ln;
   539	    listRewind(mainThreadProcessingClients[t->id], &li);
   540	    /* Phase 1: Issue prefetch instructions for client struct and pending_cmds.
   541	     * These prefetches will bring data into cache asynchronously. */
   542	    for (int i = 0; i < to_prefetch && (ln = listNext(&li)); i++) {
   543	        c[i] = listNodeValue(ln);
   544	        redis_prefetch_read(c[i]);
   545	        redis_prefetch_read(&c[i]->pending_cmds);
   546	        redis_prefetch_read(&c[i]->io_deferred_objects);
   547	    }
   548	    /* Phase 2: Access client data (now likely in cache) and add to batch.
   549	     * Also prefetch additional fields (reply, mem_usage_bucket) that will be
   550	     * needed later during command execution. */
   551	    for (int i = 0; i < to_prefetch; i++) {
   552	        if (addCommandToBatch(c[i]) == C_ERR) break;
   553	        if (c[i]->reply) redis_prefetch_read(c[i]->reply);
   554	        redis_prefetch_read(&c[i]->mem_usage_bucket);
   555	        if (c[i]->io_deferred_objects) redis_prefetch_read(c[i]->io_deferred_objects);
   556	        clients++;
   557	    }
   558	    /* Prefetch the commands in the batch. */
   559	    prefetchCommands();
   560	    return clients;
   561	}
