   771	/* Processing clients that have finished executing commands from the main thread.
   772	 * If the client is not binded to the event loop, we should bind it first and
   773	 * install read handler. If the client still has query buffer, we should process
   774	 * the input buffer. If the client has pending reply, we just reply to client,
   775	 * and then install write handler if needed. */
   776	int processClientsFromMainThread(IOThread *t) {
   777	    pthread_mutex_lock(&t->pending_clients_mutex);
   778	    listJoin(t->processing_clients, t->pending_clients);
   779	    pthread_mutex_unlock(&t->pending_clients_mutex);
   780	    size_t processed = listLength(t->processing_clients);
   781	    if (processed == 0) return 0;
   782	
   783	    listIter li;
   784	    listNode *ln;
   785	    listRewind(t->processing_clients, &li);
   786	    while((ln = listNext(&li))) {
   787	        client *c = listNodeValue(ln);
   788	        serverAssert(!(c->io_flags & (CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED)));
   789	        /* Main thread must handle clients with CLIENT_CLOSE_ASAP flag, since
   790	         * we only set io_flags when clients in io thread are freed ASAP. */
   791	        serverAssert(!(c->flags & CLIENT_CLOSE_ASAP));
   792	
   793	        /* Link client in IO thread clients list first. */
   794	        serverAssert(c->io_thread_client_list_node == NULL);
   795	        listUnlinkNode(t->processing_clients, ln);
   796	        listLinkNodeTail(t->clients, ln);
   797	        c->io_thread_client_list_node = listLast(t->clients);
   798	
   799	        /* The client now is in the IO thread, let's free deferred objects. */
   800	        freeClientDeferredObjects(c, 0);
   801	
   802	        /* The client is asked to close, we just let main thread free it. */
   803	        if (c->io_flags & CLIENT_IO_CLOSE_ASAP) {
   804	            enqueuePendingClientsToMainThread(c, 1);
   805	            continue;
   806	        }
   807	
   808	        /* Enable read and write and reset some flags. */
   809	        c->io_flags |= CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED;
   810	        c->io_flags &= ~(CLIENT_IO_PENDING_COMMAND | CLIENT_IO_PENDING_CRON);
   811	
   812	        /* Only bind once, we never remove read handler unless freeing client. */
   813	        if (!connHasEventLoop(c->conn)) {
   814	            connRebindEventLoop(c->conn, t->el);
   815	            serverAssert(!connHasReadHandler(c->conn));
   816	            connSetReadHandler(c->conn, readQueryFromClient);
   817	        }
   818	
   819	        /* Add the client to the compression clients list. */
   820	        if (c->compression_state != NULL &&
   821	            c->io_thread_compression_clients_node == NULL)
   822	        {
   823	            listAddNodeTail(t->compression_clients, c);
   824	            c->io_thread_compression_clients_node = listLast(t->compression_clients);
   825	        }
   826	
   827	        /* If the client has pending replies, write replies to client. */
   828	        if (clientHasPendingReplies(c)) {
   829	            writeToClient(c, 0);
   830	            if (!(c->io_flags & CLIENT_IO_CLOSE_ASAP) && clientHasPendingReplies(c)) {
   831	                connSetWriteHandler(c->conn, sendReplyToClient);
   832	            }
   833	        }
   834	        /* If everything has been flushed, drop any stale write handler so the IO
   835	         * thread event loop doesn't keep firing writable (EPOLLOUT) on an idle
   836	         * client. */
   837	        if (!(c->io_flags & CLIENT_IO_CLOSE_ASAP) && !clientHasPendingReplies(c)) {
   838	            serverAssert(connHasEventLoop(c->conn));
   839	            connSetWriteHandler(c->conn, NULL);
   840	        }
   841	    }
   842	    /* All clients must are processed. */
   843	    serverAssert(listLength(t->processing_clients) == 0);
   844	    return processed;
   845	}
