   892	/* Periodically transfer part of clients to the main thread for processing. */
   893	void IOThreadClientsCron(IOThread *t) {
   894	    /* Process at least a few clients while we are at it, even if we need
   895	     * to process less than CLIENTS_CRON_MIN_ITERATIONS to meet our contract
   896	     * of processing each client once per second. */
   897	    int iterations = listLength(t->clients) / IO_DEFAULT_HZ;
   898	    if (iterations < CLIENTS_CRON_MIN_ITERATIONS) {
   899	        iterations = CLIENTS_CRON_MIN_ITERATIONS;
   900	    }

